/**
 * markdown.js — escape-first renderer for the safe markdown subset Max emits.
 *
 * Works as a plain <script> in the browser (attaches window.MaxMarkdown) and
 * as an ES module under node (test/markdown.test.js imports it directly), so
 * the exact shipped rendering logic is what the tests exercise.
 *
 * Safety: every piece of source text is HTML-escaped first, and every tag is
 * generated by this file. Model output can never introduce raw HTML, so a
 * hostile reply cannot inject scripts or markup.
 *
 * Covered: **bold**, *italic* / _italic_, ***bold italic***, ~~strike~~,
 * inline `code`, fenced code blocks, unordered and ordered lists, ###
 * headings, single-newline becomes <br>, blank line starts a new paragraph.
 */

export const mdEscape = (s) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;')
   .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

export function renderMarkdown(src) {
  // fenced code blocks → placeholders (escaped at extraction)
  const fences = [];
  let text = String(src).replace(/```[a-z]*\n?([\s\S]*?)```/gi, (_m, code) => {
    fences.push('<pre><code>' + mdEscape(code.replace(/\n+$/, '')) + '</code></pre>');
    return '\u0000F' + (fences.length - 1) + '\u0000';
  });

  text = mdEscape(text);

  // inline code → placeholders so emphasis never rewrites inside it
  const spans = [];
  text = text.replace(/`([^`\n]+)`/g, (_m, code) => {
    spans.push('<code>' + code + '</code>');
    return '\u0000C' + (spans.length - 1) + '\u0000';
  });

  // emphasis, per line — runs before block parsing so it never touches the
  // tags we generate. Tight bounds keep "5 * 3 * 2" literal.
  const emphasize = (line) => line
    .replace(/\*\*\*(?!\s)([^*]+?)(?<!\s)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(?!\s)([^*]+?)(?<!\s)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(])\*(?!\s)([^*\n]+?)(?<!\s)\*(?=$|[\s).,!?;:])/, '$1<em>$2</em>')
    .replace(/(^|[\s(])_(?!\s)([^_\n]+?)(?<!\s)_(?=$|[\s).,!?;:])/, '$1<em>$2</em>')
    .replace(/~~(?!\s)([^~]+?)(?<!\s)~~/g, '<del>$1</del>');

  const out = [];
  let list = null;
  let para = [];
  const flushPara = () => { if (para.length) { out.push('<p>' + para.join('<br>') + '</p>'); para = []; } };
  const flushList = () => { if (list) { out.push('</' + list + '>'); list = null; } };

  for (const raw of text.split('\n')) {
    const line = raw.trimEnd();
    if (!line.trim()) { flushPara(); flushList(); continue; }
    // fence placeholders stand alone as blocks, never inside <p>
    if (/^\u0000F\d+\u0000$/.test(line.trim())) { flushPara(); flushList(); out.push(line.trim()); continue; }
    const heading = line.match(/^\s{0,3}#{1,6}\s+(.*)$/);
    if (heading) { flushPara(); flushList(); out.push('<h3>' + emphasize(heading[1]) + '</h3>'); continue; }
    const ul = line.match(/^\s*[-*+]\s+(.*)$/);
    const ol = line.match(/^\s*\d+[.)]\s+(.*)$/);
    if (ul || ol) {
      flushPara();
      const kind = ul ? 'ul' : 'ol';
      if (list !== kind) { flushList(); out.push('<' + kind + '>'); list = kind; }
      out.push('<li>' + emphasize((ul || ol)[1]) + '</li>');
      continue;
    }
    flushList();
    para.push(emphasize(line));
  }
  flushPara();
  flushList();

  return out.join('')
    .replace(/\u0000C(\d+)\u0000/g, (_m, i) => spans[+i])
    .replace(/\u0000F(\d+)\u0000/g, (_m, i) => fences[+i]);
}

// browser global (skipped under node, where the tests import the exports)
if (typeof window !== 'undefined') {
  window.MaxMarkdown = { renderMarkdown, mdEscape };
}
